//! Certified panel coefficients for ln on the binary significand [1, 2).
//!
//! Thirty-two panels of width 1/32, degree 8, in the centred variable
//! u = m - c. Generated by the Sollya script under formal/sollya;
//! the absolute-error constant sits strictly above every supnorm upper
//! endpoint from that run (worst endpoint about 5.43e-17).

/// Width of one panel on [1, 2).
pub(crate) const LN_PANEL_WIDTH: f64 = 1.0 / 32.0;
pub(crate) const LN_PANELS: usize = 32;
pub(crate) const LN_DEGREE: usize = 8;
/// Strict upper bound on the absolute polynomial error, above the Sollya
/// supnorm endpoint `0x1.f48729117040bf06373d6p-55`.
pub const LN_POLY_ABS_BOUND: f64 = 6.0e-17;
/// `ln(2)` as an IEEE-754 binary64 bit pattern. Matches `f64::consts::LN_2`.
pub const LN2_BITS: u64 = 0x3fe6_2e42_fefa_39ef;

const _: [(); 288] = [(); LN_PANELS * (LN_DEGREE + 1)];
const _: () = assert!(std::f64::consts::LN_2.to_bits() == LN2_BITS);
const _: () = assert!(LN_POLY_ABS_BOUND > 5.4e-17 && LN_POLY_ABS_BOUND < 1.0e-15);

