/// ln(m) for m in [1, 2), from the certified panel polynomial.
///
/// A power of two (m = 1) returns 0. The Sollya bound covers the
/// polynomial; Horner evaluation adds a few extra units in the last
/// place and is measured against libm, not folded into the constant.
#[must_use]
pub fn ln_reduced(m: f64) -> f64 {
    debug_assert_eq!(LN_PANEL_COEFFS[0].len(), LN_DEGREE + 1);
    if m == 1.0 {
        return 0.0;
    }
    let scaled = (m - 1.0) / LN_PANEL_WIDTH;
    let mut panel = scaled as usize;
    if panel >= LN_PANELS {
        panel = LN_PANELS - 1;
    }
    let centre = 1.0 + (panel as f64 + 0.5) * LN_PANEL_WIDTH;
    let u = m - centre;
    let mut acc = 0.0f64;
    for &bits in LN_PANEL_COEFFS[panel].iter().rev() {
        acc = acc.mul_add(u, f64::from_bits(bits));
    }
    acc
}
